/bin/bash -lc "python3 - <<'PY'
import cv2,numpy as np
im=cv2.imread('first_frame.png'); hsv=cv2.cvtColor(im,cv2.COLOR_BGR2HSV); gray=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
# connected components dark masks in target zone, several thresholds
for th in [15,25,35,45,55,65,75,85]:
 m=(gray<th).astype(np.uint8); n, lab, st, cen=cv2.connectedComponentsWithStats(m,8)
 cs=[]
 for i in range(1,n):
  x,y,w,h,a=st[i]
  if a>50 and y<400 and y+h>100: cs.append((a,x,y,w,h,tuple(np.round(cen[i],1))))
 print('th',th, sorted(cs,reverse=True)[:20])
# HSV components saturated warm around balls
for cond,name in [(((hsv[:,:,0]<25)&(hsv[:,:,1]>60)&(hsv[:,:,2]>50)),'warm'),(((hsv[:,:,1]<45)&(gray>40)&(gray<180)),'gray')]:
 m=cond.astype(np.uint8); n,l,st,cen=cv2.connectedComponentsWithStats(m,8)
 cs=[]
 for i in range(1,n):
  x,y,w,h,a=st[i]
  if a>20: cs.append((a,x,y,w,h,tuple(np.round(cen[i],1))))
 print(name,sorted(cs,reverse=True)[:30])
PY"
